import { createHash, randomUUID } from 'node:crypto';
import { readContract } from './generation-contract.js';
export const stages = ['Arquitectura', 'Implementación', 'Pruebas', 'Revisión', 'Documentación'];
export function text(value, name, max = 20000) {
  if (typeof value !== 'string' || !value.trim() || value.length > max)
    throw Object.assign(new Error(name + ': contenido obligatorio o demasiado largo.'), { status: 400 });
  return value.trim();
}
export function initialPlan(brief) {
  return '# Work plan — manual draft\n\n' +
    'This outline was NOT generated by an agent. Complete and review it before approval.\n\n' +
    '## Objective\n' + brief.description + '\n\n## Context and constraints\n' + brief.context +
    '\n\n## Included scope\n- [To define]\n\n## Out of scope\n- [To define]\n\n' +
    '## Architecture and planned files\n- [To define]\n\n' +
    '## Tasks and owners\n- Architect: define contracts and structure.\n' +
    '- Implementer: build according to approved contracts.\n' +
    '- Tester: propose positive, negative, and persistence checks.\n' +
    '- Reviewer: inspect changes and results independently.\n' +
    '- Documenter: record setup, use, and limitations.\n\n' +
    '## Mandatory interface baseline\n- i18n with English/Spanish catalogs, English by default, and a persisted selector.\n' +
    '- dark/light themes with a persisted selector, readable contrast, and keyboard access.\n' +
    '- Include language and themes in implementation, review, documentation, and proposed checks.\n\n' +
    '## Verifiable acceptance criteria\n- [To define]\n\n' +
    '## Risks and open questions\n- [To define]\n';
}
export function createProject(input) {
  const brief = { name: text(input.name, 'Nombre', 100), description: text(input.description, 'Descripción'), context: text(input.context || 'Sin contexto adicional.', 'Contexto') };
  const now = new Date().toISOString();
  return { id: randomUUID(), brief, revision: 1, plan: initialPlan(brief), status: 'draft', approval: null,
    stages: stages.map(name => ({ name, status: 'not_connected' })),
    events: [{ at: now, message: 'Proyecto creado. Borrador manual; ningún agente ejecutado.' }], createdAt: now };
}
export function requireRevision(project, revision) {
  if (revision !== project.revision) throw Object.assign(new Error('El plan cambió. Recarga antes de continuar.'), { status: 409 });
}
export function editPlan(project, input) {
  requireRevision(project, input.revision);
  project.planOrigin = project.planOrigin === 'codex' || project.planOrigin === 'codex-edited' ? 'codex-edited' : 'manual';
  project.plan = text(input.plan, 'Plan', 50000);
  project.revision += 1; project.approval = null; project.status = 'draft';
  project.needsReplanning = false;
  project.events.push({ at: new Date().toISOString(), message: 'Plan editado; aprobación anterior invalidada.' });
  return project;
}
export function approvePlan(project, input) {
  requireRevision(project, input.revision);
  if (project.plan.includes('```aipb-contract-v2')) readContract(project.plan);
  if (project.needsReplanning) throw Object.assign(new Error('Actualiza el plan para incorporar los nuevos requisitos antes de aprobar.'), { status: 400 });
  if (project.plan.includes('[Por definir]') || project.plan.includes('[To define]')) throw Object.assign(new Error('Complete the pending sections before approval.'), { status: 400 });
  if (project.approval) throw Object.assign(new Error('Esta revisión ya está aprobada.'), { status: 409 });
  project.approval = { revision: project.revision, sha256: createHash('sha256').update(project.plan).digest('hex'), at: new Date().toISOString() };
  project.status = 'approved';
  project.events.push({ at: project.approval.at, message: 'Plan aprobado. La implementación requiere consentimiento separado.' });
  return project;
}

export function continueProject(project, input) {
  requireRevision(project, input.revision);
  const changes = text(input.changes, 'Nuevos requisitos', 10000);
  const context = text(project.brief.context + '\n\nSolicitud de continuacion:\n' + changes, 'Contexto acumulado');
  project.continuation = { fromRevision: project.revision, changes, at: new Date().toISOString() };
  project.brief = { ...project.brief, context };
  project.revision += 1;
  project.approval = null;
  project.status = 'draft';
  project.needsReplanning = true;
  project.events.push({ at: project.continuation.at, message: 'Continuacion solicitada. Plan anterior conservado como referencia; actualizar y aprobar antes de implementar.' });
  return project;
}
